package io.github.diodeme.ji.relay;

import io.github.diodeme.ji.storage.sqlite.SqliteMigration;
import io.github.diodeme.ji.storage.sqlite.SqliteMigrationManager;
import io.github.diodeme.ji.storage.sqlite.SqliteSchema;
import java.nio.file.Path;
import java.util.List;
import java.util.Set;

/** Forward-only catalog for Relay-owned routing and pairing metadata. */
final class RelayDatabaseMigrations {
    private static final Set<String> TABLES = Set.of("relay_device", "relay_host", "relay_invitation", "relay_grant");
    private static final Set<String> LEGACY_HOST_COLUMNS = Set.of(
            "tenant_id", "host_id", "noise_key_algorithm", "public_key", "protocol_version", "release_version", "registered_at");
    private static final Set<String> CURRENT_HOST_COLUMNS = Set.of(
            "tenant_id", "host_id", "auth_algorithm", "auth_public_key", "noise_key_algorithm", "public_key",
            "noise_public_key", "protocol_version", "release_version", "registered_at");

    private RelayDatabaseMigrations() {}

    static void migrate(Path database) {
        new SqliteMigrationManager(database, "relay", List.of(
                new SqliteMigration(1, "relay-metadata", List.of(
                        "CREATE TABLE IF NOT EXISTS relay_device (tenant_id TEXT NOT NULL, device_id TEXT NOT NULL, auth_algorithm TEXT NOT NULL, public_key BLOB NOT NULL, roles TEXT NOT NULL, created_at TEXT NOT NULL, revoked_at TEXT, PRIMARY KEY (tenant_id, device_id))",
                        "CREATE TABLE IF NOT EXISTS relay_host (tenant_id TEXT NOT NULL, host_id TEXT NOT NULL, noise_key_algorithm TEXT NOT NULL, public_key BLOB NOT NULL, protocol_version INTEGER NOT NULL, release_version TEXT NOT NULL, registered_at TEXT NOT NULL, PRIMARY KEY (tenant_id, host_id))",
                        "CREATE TABLE IF NOT EXISTS relay_invitation (tenant_id TEXT NOT NULL, invitation_id TEXT NOT NULL, issuer_device_id TEXT NOT NULL, host_ids TEXT NOT NULL, secret_hash BLOB NOT NULL, fingerprint TEXT NOT NULL, expires_at TEXT NOT NULL, confirmed_at TEXT, consumed_at TEXT, PRIMARY KEY (tenant_id, invitation_id))",
                        "CREATE TABLE IF NOT EXISTS relay_grant (tenant_id TEXT NOT NULL, host_id TEXT NOT NULL, device_id TEXT NOT NULL, requested_scopes TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (tenant_id, host_id, device_id))")),
                new SqliteMigration(2, "typed-host-identity", List.of(
                        "ALTER TABLE relay_host ADD COLUMN auth_algorithm TEXT NOT NULL DEFAULT 'ed25519-x509'",
                        "ALTER TABLE relay_host ADD COLUMN auth_public_key BLOB NOT NULL DEFAULT X''",
                        "ALTER TABLE relay_host ADD COLUMN noise_public_key BLOB NOT NULL DEFAULT X''",
                        "DELETE FROM relay_host WHERE length(auth_public_key) = 0 OR length(noise_public_key) = 0"))), connection -> {
            var schema = SqliteSchema.tables(connection);
            if (schema.isEmpty()) return 0;
            if (!schema.keySet().equals(TABLES)) return -1;
            Set<String> host = schema.get("relay_host");
            if (host.equals(LEGACY_HOST_COLUMNS)) return 1;
            if (host.equals(CURRENT_HOST_COLUMNS)) return 2;
            return -1;
        }).migrate();
    }
}
